        'org_refund_not_eligible' => ['code' => 4031, 'status' => 409, 'meaning' => 'The target invoice of the operator\'s signed fee-refund command is not a paid, unrefunded plan invoice of this workspace, or the workspace already took its one refund. No customer route returns this code; the fee refund exists only as that operator command. Packs are never refundable regardless of this check.'],
        'org_refund_currency_mismatch' => ['code' => 4032, 'status' => 409, 'meaning' => 'No longer emitted: no current route returns this code. It stays in the catalog, with its code, slug and status unchanged, for clients that may still key on it. The signed admin fee-refund command answers its own currency_mismatch refusal instead. It used to mean: The Stripe charge settled in a currency different from the invoice\'s currency, so a partial refund amount cannot be computed. Contact support for a manual refund.'],
        'org_tax_id_invalid' => ['code' => 4033, 'status' => 400, 'meaning' => 'The tax id or its label does not match a shape this system accepts. This is a shape check only, never a registry lookup against a tax authority.'],
