        'agent_claim_invalid' => ['code' => 4036, 'status' => 401, 'meaning' => 'The claim secret did not match, or the signup does not exist, was refunded, or has expired, or it was already claimed and the claim token can no longer be re-minted (it was used, revoked, or one hour has passed since it was minted). These cases answer identically on purpose. A correct-secret retry of a completed claim whose token is still unused and within that hour answers 201 with a new token instead. A confirmed-but-unpaid Checkout Session answers wrong_state (4001) instead once the secret itself has checked out.'],
        'agent_pack_locked' => ['code' => 4037, 'status' => 403, 'meaning' => 'An agent account\'s pack tier does not allow the requested pack yet. A fresh agent account is limited to the small packs; a larger pack unlocks only once enough prior payments have settled past the dispute window. Reached on POST /v1/agent/accounts (signup, always tier 0) and POST /v1/billing/purchase for an agent caller. The response carries details.allowed_packs, the pack ids currently buyable; retry with one of those. Never reached by a human account.'],
        'agent_purchase_capped' => ['code' => 4038, 'status' => 429, 'meaning' => 'An agent account has reached its per-credential spend cap for the current rolling window: 3 purchases, paid or declined, in the trailing 24 hours. The cap is counted per account across every credential the account has ever held, not per token, so rotating a credential does not reset it. Reached on POST /v1/billing/purchase for an agent caller, and for a human account\'s personal access token caller, which has its own cap of the same size counted the same way. A human purchasing through the app is never capped. The response carries details.limit, details.window_seconds and details.retry_after_seconds, and a Retry-After header naming the same wait in seconds.'],
        'org_last_admin' => ['code' => 4039, 'status' => 409, 'meaning' => 'A rights change or a member removal would leave the workspace with no member carrying is_admin. This is refused by a count check evaluated inside the update itself, not by a pre-read, so two admins concurrently dropping each other\'s flag cannot both succeed.'],
        'org_rights_invalid' => ['code' => 4040, 'status' => 422, 'meaning' => 'The member rights update carried no changed field, or monthly_cap_seconds fell outside the allowed range for a pooled member cap.'],
